insert into public.site_content (key, value) values ('hero', '{"title":"Ku gjuha hap botën.","lede":"Gjimnazi i shkencave shoqërore-gjuhësore në Prishtinë, që mban emrin e gjuhëtarit Eqrem Çabej. Gjuhët, mendimi kritik dhe shoqëria janë në qendër të çdo dite mësimi.","image_url":null,"image_alt":null,"primary_cta":{"label":"Njihu me programin","href":"/programet"},"secondary_cta":{"label":"Na kontakto","href":"/kontakti"}}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('intro', '{"heading":"Një shkollë e ndërtuar rreth gjuhës.","body":"Që nga viti 1990, Gjimnazi \"Eqrem Çabej\" është profilizuar në gjuhë. Nga viti shkollor 2021–2022, me vendim të Ministrisë së Arsimit, shkolla funksionon si gjimnaz i shkencave shoqërore-gjuhësore. Ndërtesa e sotme në rrugën \"Remzi Salihu\" është shtëpia e shkollës që nga viti shkollor 2012–2013.","vision":"Shkolla synon që brenda dhjetë vjetësh të bëhet shkollë elitare dhe gjithëpërfshirëse.","mission":"Të kontribuojë në zhvillimin maksimal të secilit nxënës.","source":"Plani Zhvillimor i Shkollës 2021–2024"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('history', '[{"period":"Fillimet","title":"Në objektin e Shkollës Normale","text":"Shkolla e nisi punën në ambientet e ish-Shkollës Normale në Prishtinë."},{"period":"Më pas","title":"Gjimnaz matematikor, pastaj kulturologjik","text":"Përgjatë viteve, shkolla ndryshoi profil: fillimisht si gjimnaz matematikor dhe më pas si gjimnaz kulturologjik."},{"period":"1990","title":"Gjimnaz filologjik","text":"Shkolla profilizohet në gjuhë dhe bëhet gjimnaz filologjik."},{"period":"2012–2013","title":"Ndërtesa e re","text":"Mësimi zhvendoset në ndërtesën e tanishme, në rrugën \"Remzi Salihu\" nr. 61."},{"period":"2021–2022","title":"Shkencat shoqërore-gjuhësore","text":"Me vendim të MASHTI-t (nr. 2-854), shkolla profilizohet si gjimnaz i shkencave shoqërore-gjuhësore."}]'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('enrollment', '{"heading":"Regjistrimi në klasën e dhjetë","body":"Kushtet, afatet dhe konkursi i regjistrimit publikohen nga shkolla dhe Drejtoria Komunale e Arsimit. Sapo të konfirmohen për vitin e ri shkollor, do t''i gjeni këtu.","cta_label":"Pyet për regjistrimin","cta_href":"/kontakti","verification":"pending"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('contact', '{"address":"Rr. \"Remzi Salihu\" nr. 61","city":"Prishtinë, Kosovë","phone":null,"email":null,"hours":null,"map_query":"Gjimnazi Eqrem Çabej, Rruga Remzi Salihu 61, Prishtinë"}'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('socials', '[{"label":"Instagram","href":"https://www.instagram.com/gjimnazi.eqremcabej/","verified":true}]'::jsonb) on conflict (key) do nothing;
insert into public.site_content (key, value) values ('student_info', '{"heading":"Gjithçka që të duhet si nxënës","items":[{"title":"Këshilli i Nxënësve","body":"Nxënësit përfaqësohen përmes Këshillit të Nxënësve, pjesë e strukturës organizative të shkollës.","verification":"verified"},{"title":"Biblioteka","body":"Shkolla ka bibliotekë me bibliotekist/e. Orari i hapjes do të publikohet këtu.","verification":"verified"},{"title":"Kabinetet","body":"Shkolla ka kabinet të gjuhëve, kabinete të biologjisë dhe fizikës, kabinet të artit muzikor dhe kabinet të TIK-ut.","verification":"verified"},{"title":"Orari i mësimit","body":"Orari i ndërrimeve dhe i orëve mësimore do të publikohet nga administrata e shkollës.","verification":"pending"},{"title":"Kalendari akademik","body":"Afatet e semestrave, pushimeve dhe provimeve do të shtohen sapo të konfirmohen.","verification":"pending"},{"title":"Matura shtetërore","body":"Informatat për përgatitjen dhe afatet e Maturës do të publikohen në seksionin e njoftimeve.","verification":"pending"}]}'::jsonb) on conflict (key) do nothing;
