insert into public.programs (slug, name, short_name, tagline, summary, overview, outcomes, pathways, grades, sort_order, verification, source_note, status, published_at) values ('shkencat-shoqerore-gjuhesore', 'Gjimnazi i shkencave shoqërore-gjuhësore', 'Shoqëror-gjuhësor', 'Gjuhët, shoqëria dhe mendimi kritik.', 'Profili i shkollës që nga viti shkollor 2021–2022, me gjuhët dhe shkencat shoqërore në qendër të planit mësimor.', 'Me vendim të MASHTI-t (nr. 2-854), Gjimnazi "Eqrem Çabej" funksionon si gjimnaz i shkencave shoqërore-gjuhësore. Programi ndërtohet mbi traditën e shkollës si gjimnaz filologjik që nga viti 1990. Mësimdhënia përfshin gjuhë shqipe, gjuhë të huaja dhe latinisht, krahas shkencave shoqërore, historisë, psikologjisë, matematikës, shkencave natyrore, arteve, edukatës fizike dhe TIK-ut.', array[]::text[], array[]::text[], 'Klasat X–XII', 1, 'verified', 'Plani Zhvillimor i Shkollës 2021–2024', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
