insert into public.programs (slug, name, short_name, tagline, summary, overview, outcomes, pathways, grades, sort_order, verification, source_note, status, published_at) values ('gjuha-gjermane', 'Programi i gjuhës gjermane', 'Gjuha gjermane', 'Gjermanishtja si gjuhë e dytë e huaj.', 'Gjermanishtja mësohet nga mësimdhënës të specializuar në shkollë. Detajet e programit, certifikimet dhe bashkëpunimet do të publikohen pasi të konfirmohen.', 'Faqja e mëparshme e shkollës e paraqiste gjuhën gjermane si program të veçantë, të zhvilluar në bashkëpunim me partnerë nga Gjermania. Këto informata, përfshirë certifikimet dhe shkëmbimet, janë në pritje të konfirmimit nga administrata e shkollës para se të publikohen si fakte.', array[]::text[], array[]::text[], 'Klasat X–XII', 2, 'pending', 'Faqja e mëparshme e shkollës; e pakonfirmuar', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
