insert into public.clubs (slug, name, summary, description, is_media_club, sort_order, verification, status, published_at) values ('klubi-i-medias', 'Klubi i Medias', 'Video, podkaste dhe gazetari nga nxënësit, për nxënësit.', 'Klubi i Medias është hapësira ku nxënësit mësojnë të tregojnë histori: filmojnë, montojnë, intervistojnë dhe publikojnë. Përbërja e ekipit, takimet dhe produksionet do të publikohen nga mentorët e klubit.', true, 1, 'pending', 'published', '2025-09-01T08:00:00Z') on conflict (slug) do nothing;
